mapper.select:
SELECT a.fbx03_file_id AS file_id, a.fbx03_box_id AS box_id, a.fbx03_dcr_class_id AS dcr_class_id,
       NULL AS dcr_class_name, a.fbx03_emp_id AS emp_id, NULL AS emp_name, a.fbx03_crt_date AS crt_date, NULL AS file_name
  FROM fbx03_file a
       INNER JOIN fbx01_box b ON b.fbx01_box_id = a.fbx03_box_id
 WHERE b.fbx01_company_id = #{companyId}
   AND a.fbx03_box_id = #{boxId}
   AND a.fbx03_file_id = #{fileId}
